// 探索段階の疑いを、演出完了後の画面と通常入力で確定する。製品コードは変更しない。
import fs from 'node:fs';
import {chromium} from 'playwright-core';
const out='artifacts/responsive-reevaluation-20260913';
const browser=await chromium.launch({executablePath:'C:/Program Files/Google/Chrome/Application/chrome.exe',headless:true});
const results=[];let c,p;
async function start(w,h,lang='en',mobile=false){await c?.close();c=await browser.newContext({viewport:{width:w,height:h},hasTouch:mobile,isMobile:mobile,deviceScaleFactor:mobile?3:1,reducedMotion:'no-preference'});await c.route('https://**',r=>r.abort());await c.addInitScript(lang=>{if(location.protocol==='http:')localStorage.setItem('gaia:language:v1',lang);},lang);p=await c.newPage();p.setDefaultTimeout(8000);}
async function map(n){await p.goto('http://127.0.0.1:4492/#world-'+n);await p.locator('#gaia-boot').waitFor({state:'hidden'});await p.waitForTimeout(7000);await p.waitForFunction(n=>GaiaMapPlayback.getState().ready&&Number(document.querySelector('#japan-mode-number').textContent)===n&&!document.querySelector('#japan-layer').classList.contains('is-map-title-transitioning'),n);}
async function shot(id){await p.screenshot({path:`${out}/${id}.png`,scale:'css'});}
async function geometry(selector){return p.locator(selector).evaluateAll(es=>es.map(e=>{const r=e.getBoundingClientRect(),h=document.elementFromPoint(r.x+r.width/2,r.y+r.height/2);return {text:e.textContent.trim().slice(0,180),rect:r.toJSON(),font:getComputedStyle(e).fontSize,hit:!!h&&e.contains(h),cover:h&&!e.contains(h)?h.id||h.className:null,client:e.clientHeight,scroll:e.scrollHeight,top:e.scrollTop};}));}
function record(id,data){results.push({id,...data});fs.writeFileSync(`${out}/confirm.json`,JSON.stringify(results,null,2));console.log('CONFIRM',id);}
try{
 for(const [w,h,n]of [[1200,700,8],[901,700,70],[1024,768,26],[1366,768,70],[1920,1080,26]]){
  await start(w,h);await map(n);await shot(`confirmed-${w}-map${n}`);
  const next='.japan-heading [data-map-heading-step="1"]',before=await geometry(next);
  let clicked=true,error=null;try{await p.locator(next).click({timeout:1800});}catch(e){clicked=false;error=e.message.slice(0,1200);}if(clicked)await p.waitForTimeout(600);
  record(`heading-${w}-${n}`,{before,clicked,error,number:await p.locator('#japan-mode-number').textContent()});
  if(n===26){await map(n);const before=await geometry('.japan-credits');await p.locator('.japan-credits').hover();await p.mouse.wheel(0,700);await p.waitForTimeout(400);await shot(`confirmed-credit-${w}`);const after=await geometry('.japan-credits');const links=await geometry('.japan-credits a');const legends=await geometry('.gaia-estat-heat-legend,.gaia-estat-prefecture-tooltip');record(`credit-legend-${w}`,{before,after,links,legends});}
 }
 await start(1024,768,'ja');await map(26);
 await p.locator('[data-map-menu-toggle]').focus();await p.waitForTimeout(1400);await p.keyboard.press('ArrowDown');
 await p.locator('#map-dock-bank-popover [role="tab"][data-map-scope="world"]').click();await p.waitForTimeout(1400);await shot('confirmed-menu-world');
 await p.locator('#map-dock-bank-popover [role="tab"][data-map-scope="japan"]').click();await p.waitForTimeout(1400);await shot('confirmed-menu-japan');await p.keyboard.press('Escape');await p.waitForTimeout(700);await shot('confirmed-menu-escape');record('menu-escape',{visible:await p.locator('#map-dock-bank-popover').isVisible(),focus:await p.evaluate(()=>document.activeElement.outerHTML.slice(0,250))});
 await start(375,667,'en',true);await map(40);await p.locator('[data-map-menu-toggle]').click();await p.locator('#map-mobile-sheet [role="tab"][data-map-scope="japan"]').click();
 const last=p.locator('[data-mobile-exhibit="69"]');await last.scrollIntoViewIfNeeded();await p.waitForTimeout(1400);await shot('confirmed-mobile-menu69');await last.click();await p.waitForFunction(()=>Number(document.querySelector('#japan-mode-number').textContent)===69);await p.waitForTimeout(4000);await shot('confirmed-mobile-map69');record('mobile-menu-select',{number:69});
 for(const [w,h]of [[320,568],[844,390],[1920,1080]]){
  await start(w,h,w===320?'ja':'en',w<=900);await p.goto('http://127.0.0.1:4492/#character');await p.locator('#gaia-boot').waitFor({state:'hidden'});await p.locator('[data-character-select="sakuya"]').click();await p.waitForTimeout(6000);await p.locator('#character-book-profile').scrollIntoViewIfNeeded();await p.waitForTimeout(700);await shot(`confirmed-character-${w}-profile`);await p.locator('.character-book-hero-quote').scrollIntoViewIfNeeded();await p.waitForTimeout(700);await shot(`confirmed-character-${w}-quote`);record(`character-${w}`,{panels:await geometry('.character-book-hero-detail,.character-book-hero-figure'),overflow:await p.evaluate(()=>document.documentElement.scrollWidth-innerWidth)});
 }
 await start(320,568,'en',true);await p.goto('http://127.0.0.1:4492/#sound');await p.locator('#gaia-boot').waitFor({state:'hidden'});await p.locator('[data-sound-track="trueend"]').click();await p.waitForTimeout(6000);await shot('confirmed-sound-selected12');const before=await geometry('#sound-play');const playing1=await p.locator('#sound-play').getAttribute('aria-pressed');await p.locator('#sound-play').click();await p.waitForTimeout(700);const playing2=await p.locator('#sound-play').getAttribute('aria-pressed');await p.locator('#sound-play').click();await p.waitForTimeout(700);await shot('confirmed-sound-player');record('sound-selection-transport',{before,playing1,playing2,playing3:await p.locator('#sound-play').getAttribute('aria-pressed'),title:await p.locator('#sound-track-title').textContent()});
 for(const [w,h,lang]of [[320,568,'zh-CN'],[844,390,'en']]){
  await start(w,h,lang,true);await p.goto('http://127.0.0.1:4492/');await p.locator('#gaia-opening-sound-modal').waitFor({state:'visible'});await p.locator('#gaia-opening-sound-off').click();await p.locator('#gaia-opening-sound-modal').waitFor({state:'hidden',timeout:15000});record(`entry-confirmed-${w}`,{closed:true});
  await p.goto('http://127.0.0.1:4492/concept/');await p.waitForFunction(()=>document.body.dataset.enhanced==='true');await p.locator('.learning-courses > li').nth(2).scrollIntoViewIfNeeded();await p.waitForTimeout(2000);await shot(`confirmed-concept-${w}`);record(`concept-${w}`,{overflow:await p.evaluate(()=>document.documentElement.scrollWidth-innerWidth)});
  await p.goto('http://127.0.0.1:4528/sensors/#map');await p.waitForFunction(()=>document.documentElement.dataset.sensorView==='map');await p.waitForTimeout(4000);await shot(`confirmed-sensor-guide-${w}`);const close=p.locator('[data-feature-start]:visible');if(await close.count())await close.click();else {const x=p.locator('#gaia-mode-entry-guide button:visible').first();if(await x.count())await x.click();}await p.waitForTimeout(1000);await shot(`confirmed-sensor-map-${w}`);record(`sensor-${w}`,{overflow:await p.evaluate(()=>document.documentElement.scrollWidth-innerWidth),guideVisible:await p.locator('#gaia-mode-entry-guide').isVisible()});
 }
}catch(e){record('script-interruption',{error:e.stack});await shot('confirm-interruption').catch(()=>{});process.exitCode=1;}finally{await browser.close();}
